{
  "name": "FTDI USB 位操作 GPIO 接口器件",
  "name_en": "FTDI USB Bit-Bang GPIO Interface",
  "manufacturer": "FTDI",
  "description": "一种基于 FTDI 芯片的 USB 数字 I/O 接口器件，可在位操作模式下将 8 条引脚配置为输入或输出，并读取或驱动数字电平。实验室中常用于简单数字电路、继电器、触发线或自定义仪器接口的低速控制与状态采集。",
  "description_en": "A USB digital I/O interface based on an FTDI chip, operating in bit-bang mode to configure 8 pins as inputs or outputs and to read or drive digital logic levels. In laboratories it is commonly used for low-speed control and status acquisition with simple digital circuits, relays, trigger lines, or custom instrument interfaces.",
  "actions": [
    {
      "action_name": "auto-direction",
      "description": "获取/设置 8 位 I/O 引脚方向",
      "description_en": "Get/set the 8-bit I/O pin direction."
    },
    {
      "action_name": "auto-latch",
      "description": "获取/设置输出锁存值",
      "description_en": "Get/set the output latch value."
    },
    {
      "action_name": "auto-open",
      "description": "打开与 FTDI 位操作 I/O 设备的连接",
      "description_en": "Open the connection to the FTDI bit-bang I/O device."
    },
    {
      "action_name": "auto-port",
      "description": "获取/设置 8 位 I/O 端口状态",
      "description_en": "Get/set the 8-bit I/O port state."
    },
    {
      "action_name": "auto-read_pins",
      "description": "读取引脚当前实际状态",
      "description_en": "Read the current actual state of the pins."
    }
  ],
  "tag_hints": [
    "FTDI",
    "USB GPIO",
    "bit-bang I/O",
    "digital I/O control",
    "8-bit port",
    "trigger and relay interfacing"
  ]
}

